ALTER TABLE "driver_deductions" ADD CONSTRAINT "driver_deductions_driver_id_fkey" FOREIGN KEY ("driver_id") REFERENCES "drivers"("id") ON DELETE CASCADE ON UPDATE CASCADE;

CREATE TABLE "driver_ledger_entries" (
