ALTER TABLE "driver_ledger_entries" ADD CONSTRAINT "driver_ledger_entries_deduction_id_fkey" FOREIGN KEY ("deduction_id") REFERENCES "driver_deductions"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
